from datetime import timedelta


class TimeRangeFilter(object):
    """Filters log entries produced in a time range

    """

    def __init__(self, start_time, time_delta, **kwargs):
        """Initialize time range filter

        :param datetime.datetime start_time: log start time (Eg: datetime(2017, 1, 1, 12, 10, 1, 12)
        This will be converted to 2017-01-01 12:10:01.000012 in datetime format
        :param float time_delta: time duration in seconds (Ex: "5" or 0.002 or 0.00012)

        """
        super(TimeRangeFilter, self).__init__(**kwargs)
        self._start_time = start_time
        self._end_time = self._start_time + timedelta(seconds=time_delta)

    def __call__(self, log_entries):

        """Return log entries in time range

        :param list log_entries: log entries as input
        :return: list of log_entries within the time range


        """
        for log_entry in log_entries:
            if log_entry.timestamp is not None:
                if self._start_time <= log_entry.timestamp <= self._end_time:
                    yield log_entry
